# enumerate connected motifs of size s within bbox 4x4
def gen_motifs(s):
    res=set()
    def grow(cur):
        if len(cur)==s:
            if connected(cur): res.add(canon(cur))
            return
        nb={(r+dr,c+dc) for r,c in cur for dr,dc in((1,0),(-1,0),(0,1),(0,-1))}-{*cur}
        for q in nb:
            rs=[r for r,c in cur|{q}]; cs=[c for r,c in cur|{q}]
            if max(rs)-min(rs)<4 and max(cs)-min(cs)<4: grow(cur|{q})
    grow({(0,0)})
    return res
