            if cells: wins[(r,c)]=cells
    # exact partition via backtracking
    sols=[]
    def bt(rem,acc):
        if not rem: sols.append(list(acc)); return
        if len(sols)>50: return
        p=next(iter(rem))
        for wc,cells in wins.items():
            if p in cells and cells<=rem:
                bt(rem-cells,acc+[(wc,cells)])
    bt(obj,[])
    return sols
